const errorData = $input.first().json;

// Parse error information
const execution = errorData.execution || {};
const workflow = errorData.workflow || {};
const error = execution.error || errorData.error || {};

const errorInfo = {
  workflow_name: workflow.name || errorData.workflowName || 'Unknown',
  workflow_id: workflow.id || errorData.workflowId || 'Unknown',
  execution_id: execution.id || errorData.executionId || 'Unknown',
  error_message: error.message || errorData.message || 'Unknown error',
  error_node: error.node || errorData.nodeName || 'Unknown',
  error_type: error.name || 'ExecutionError',
  timestamp: new Date().toISOString(),

  // Determine severity
  severity: determineSeverity(workflow.name, error.message),

  // Determine if retryable
  is_retryable: isRetryable(error.message, error.name),

  // Extract client_id if available in execution data
  client_id: extractClientId(execution)
};

function determineSeverity(workflowName, errorMsg) {
  const criticalWorkflows = ['health-monitoring', 'contact-sync', 'hubspot-sync'];
  const wfLower = (workflowName || '').toLowerCase();

  if (criticalWorkflows.some(cw => wfLower.includes(cw))) return 'critical';
  if (errorMsg?.includes('timeout') || errorMsg?.includes('ECONNREFUSED')) return 'high';
  if (errorMsg?.includes('rate limit') || errorMsg?.includes('429')) return 'medium';
  return 'low';
}

function isRetryable(errorMsg, errorType) {
  const retryablePatterns = [
    'timeout', 'ECONNREFUSED', 'ECONNRESET', 'ETIMEDOUT',
    '429', '502', '503', '504', 'rate limit',
    'temporarily unavailable', 'service unavailable'
  ];
  const msg = (errorMsg || '').toLowerCase();
  return retryablePatterns.some(p => msg.includes(p.toLowerCase()));
}

function extractClientId(exec) {
  try {
    const data = exec.data || {};
    const resultData = data.resultData || {};
    const runData = resultData.runData || {};
    // Try to find client_id in any node's output
    for (const nodeName of Object.keys(runData)) {
      const nodeRuns = runData[nodeName] || [];
      for (const run of nodeRuns) {
        const items = run.data?.main?.[0] || [];
        for (const item of items) {
          if (item.json?.client_id) return item.json.client_id;
        }
      }
    }
  } catch (e) {}
  return null;
}

return [{ json: errorInfo }];
